INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Anforderungsanalyse nur für Softwareprojekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Projekte wichtig"}, {"text": "Ja", "correct": false, "because": "Nicht auf Software beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Anforderungsanalyse?', 3, '[{"text": "Klarheit über Anforderungen schaffen", "correct": true, "because": "Definiert Projektumfang"}, {"text": "Kosten senken", "correct": false, "because": "Indirekter Effekt"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Anforderungsanalyse?', 5, '[{"text": "Stakeholder-Interviews", "correct": true, "because": "Erfasst Bedürfnisse"}, {"text": "Anforderungsdokumentation", "correct": true, "because": "Fixiert Ergebnisse"}, {"text": "Code-Implementierung", "correct": false, "because": "Spätere Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anforderungsanalyse verhindert Missverständnisse. b) Sie ist einmalig und unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann angepasst werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Anforderungsanalyse?', 4, '[{"text": "Stakeholder-Bedürfnisse", "correct": false, "because": "Kern der Analyse"}, {"text": "Projektziele", "correct": false, "because": "Richtung definieren"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Anforderungsanalyse iterativ sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Oft schrittweise verfeinert"}, {"text": "Nein", "correct": false, "because": "Nicht einmalig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für die Erfassung von Anforderungen?', 3, '[{"text": "Workshops", "correct": true, "because": "Fördert Diskussion"}, {"text": "Code-Review", "correct": false, "because": "Spätere Phase"}, {"text": "Zufallsauswahl", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Anforderungsanalyse?', 5, '[{"text": "Funktionale Anforderungen", "correct": true, "because": "Beschreibt Systemverhalten"}, {"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Definiert Qualität"}, {"text": "Detaillierte Implementierung", "correct": false, "because": "Entwicklungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anforderungsanalyse spart Zeit später. b) Sie ist nur für große Projekte nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Projekte nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Anforderungsanalyse unwichtig?', 4, '[{"text": "Stakeholder-Einbindung", "correct": false, "because": "Erfasst Bedürfnisse"}, {"text": "Priorisierung", "correct": false, "because": "Definiert Reihenfolge"}, {"text": "Teamuniformen", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Anforderungsanalyse statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Kann sich ändern"}, {"text": "Ja", "correct": false, "because": "Dynamisch anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine gute Anforderungsanalyse?', 4, '[{"text": "Klarheit für Entwickler", "correct": true, "because": "Reduziert Missverständnisse"}, {"text": "Zufriedene Stakeholder", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Schnellere Implementierung", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anforderungsanalyse optional ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Grundlage für Erfolg"}, {"text": "Ja", "correct": false, "because": "Nicht empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Anforderungsanalyse?', 3, '[{"text": "Kundenerwartungen", "correct": true, "because": "Definiert Projekt"}, {"text": "Technische Details", "correct": false, "because": "Später relevant"}, {"text": "Zeitdruck", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anforderungsanalyse umfasst Machbarkeitsprüfung. b) Sie ersetzt die Entwicklung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Anforderungsanalyse?', 5, '[{"text": "Fehlentwicklungen", "correct": true, "because": "Falsche Prioritäten"}, {"text": "Höhere Kosten", "correct": true, "because": "Nachbesserungen nötig"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Verzögert Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Anforderungsanalyse unwichtig?', 3, '[{"text": "Anforderungspriorität", "correct": false, "because": "Definiert Fokus"}, {"text": "Stakeholder-Feedback", "correct": false, "because": "Kern der Analyse"}, {"text": "Farbschema", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Anforderungsanalyse agil sein?', 3, '[{"text": "Ja", "correct": true, "because": "Iterativ anpassbar"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Anforderungsanalyse technische Details enthält?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Was, nicht Wie"}, {"text": "Ja", "correct": false, "because": "Später spezifiziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für die Anforderungsanalyse?', 4, '[{"text": "Use-Case-Diagramme", "correct": true, "because": "Visualisiert Anforderungen"}, {"text": "Code-Prototypen", "correct": false, "because": "Spätere Phase"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]');
